{
  "description": "The image shows a single quadrupedal animal in right-facing profile against a plain off-white background, standing on all four limbs with its back arched. The animal is mostly covered in overlapping dark brown to gray scales, but has several large, irregular areas of pale pink, smooth, fleshy skin exposed on its dorsal mid-back, mid-flank, and rear hip. It has a small elongated head with a pointed snout facing right, stout limbs ending in large curved claws, and a long tapering scaly tail extending horizontally behind it to the right and resting on the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated and narrow with a pointed snout, gray-brown wrinkled skin, a small dark nostril at the tip, a dark round eye with fine surrounding wrinkles and lashes, and short whiskers near the mouth",
      "where": "at the front right end of the body, facing right, with the neck connecting to the scaled torso"
    },
    {
      "part": "ears",
      "looks_like": "one small rounded ear with a visible inner fold and fine short hairs around the rim",
      "where": "on the side of the head just behind and slightly above the eye, bordered above by small overlapping scales"
    },
    {
      "part": "legs",
      "looks_like": "four thick, short, muscular limbs; upper portions covered in overlapping dark scales, lower portions and joints showing pale, slightly mottled and dirty skin",
      "where": "positioned under the body, two forelegs under the chest and two hindlegs under the rear, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "four broad feet with thick pale skin and three to four long, dark brown to black, sharply curved claws per foot, with dirt around the base",
      "where": "at the bottom end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick at the base and tapering to a pointed tip, covered on top and sides with overlapping dark scales and paler skin underneath",
      "where": "extending horizontally to the right from the rear of the body, lying on the ground behind the hind feet"
    },
    {
      "part": "scales",
      "looks_like": "numerous overlapping, rounded, keratinous scales in shades of dark brown, gray and tan with ridged texture and lighter edges, arranged in diagonal rows",
      "where": "densely covering the dorsal surface, top and sides of the head, outer surfaces of the limbs, and the dorsal side of the tail"
    },
    {
      "part": "markings",
      "looks_like": "large irregular patches of pale pink, smooth, slightly wrinkled fleshy skin where scales are absent, with soft folds",
      "where": "one large patch on the mid-back, one rounded patch on the mid-flank above the foreleg, and a clustered patch on the rear hip and upper hindleg area"
    }
  ],
  "attached_objects": [],
  "animals": [
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0
}
